DECLARE
    z FLOAT;
BEGIN
    z := discrimination * (theta - difficulty);
    z := GREATEST(-30, LEAST(30, z));
    RETURN 1.0 / (1.0 + EXP(-z));
END;

DECLARE
    p FLOAT;
    delta FLOAT;
    new_theta FLOAT;
BEGIN
    p := irt_probability(current_theta, question_difficulty);
    
    IF was_correct THEN
        delta := learning_rate * (1 - p) * ABS(question_difficulty);
    ELSE
        delta := -learning_rate * p * ABS(question_difficulty);
    END IF;
    
    new_theta := current_theta + delta;
    new_theta := GREATEST(-3.0, LEAST(3.0, new_theta));
    
    RETURN new_theta;
END;

BEGIN
