DECLARE
    v_current_theta NUMERIC;
    v_question_difficulty_value NUMERIC;
    v_new_theta NUMERIC;
    v_score INT;
    v_xp_earned INT;
    v_current_xp INT;
    v_new_xp INT;
    v_current_level INT;
    v_new_level INT;
    v_quiz_id UUID;
    v_result JSON;
BEGIN
    -- Get current theta
    SELECT theta INTO v_current_theta
    FROM quiz_attempts
    WHERE user_id = p_user_id AND subject = p_subject
    ORDER BY created_at DESC
    LIMIT 1;
    
    IF v_current_theta IS NULL THEN
        v_current_theta := 0.0;
    END IF;
    
    -- Get difficulty value
    v_question_difficulty_value := get_irt_difficulty_value(p_question_difficulty);
    
    -- Update theta
    v_new_theta := update_theta(
        v_current_theta,
        v_question_difficulty_value,
        p_was_correct
    );
    
    -- Calculate score (100 for correct, 0 for wrong)
    IF p_was_correct THEN
        v_score := 100;
        v_xp_earned := 10;
    ELSE
        v_score := 0;
        v_xp_earned := 5;
    END IF;
    
    -- Update profile XP and Level
    SELECT COALESCE(xp_total, 0), COALESCE(level, 1) INTO v_current_xp, v_current_level
    FROM profiles
    WHERE id = p_user_id;
    
    v_new_xp := v_current_xp + v_xp_earned;
    v_new_level := 1 + (v_new_xp / 500);
    
    UPDATE profiles
    SET 
        xp_total = v_new_xp,
        level = v_new_level,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    -- Save to quiz_attempts with all columns
    INSERT INTO quiz_attempts (
        user_id, 
        subject, 
        topic, 
        score,
        total_q,
        xp_earned, 
        theta, 
        created_at
    ) VALUES (
        p_user_id, 
        p_subject, 
        p_topic,
        v_score,
        1, 
        v_xp_earned, 
        v_new_theta, 
        NOW()
    )
    RETURNING id INTO v_quiz_id;
    
    -- Return result
    v_result := json_build_object(
        'quiz_id', v_quiz_id,
        'old_theta', v_current_theta,
        'new_theta', v_new_theta,
        'theta_change', v_new_theta - v_current_theta,
        'score', v_score,
        'xp_earned', v_xp_earned,
        'total_xp', v_new_xp,
        'level', v_new_level,
        'was_correct', p_was_correct
    );
    
    RETURN v_result;
END;

DECLARE
    v_theta NUMERIC;
    v_difficulty_level TEXT;
    v_difficulty_value NUMERIC;
BEGIN
    SELECT qa.theta INTO v_theta
    FROM quiz_attempts qa
    WHERE qa.user_id = p_user_id AND qa.subject = p_subject
    ORDER BY qa.created_at DESC
    LIMIT 1;
    
    IF v_theta IS NULL THEN
        v_theta := 0.0;
    END IF;
    
    v_difficulty_level := get_difficulty_from_theta(v_theta);
    v_difficulty_value := get_irt_difficulty_value(v_difficulty_level);
    
    RETURN QUERY
    SELECT 
        v_difficulty_level,
        v_difficulty_value,
        v_theta,
        CASE 
            WHEN v_theta < -1.0 THEN 'Student struggling - provide easy questions'
            WHEN v_theta < 1.0 THEN 'Student at average level - provide medium questions'
            ELSE 'Student excelling - challenge with hard questions'
        END;
END;

