DECLARE
    v_recency_score NUMERIC := 0;
    v_frequency_3yr INTEGER := 0;
    v_years_since_last INTEGER := 5;
    v_chapter_weight INTEGER := 3;
    v_priority NUMERIC;
    v_record RECORD;
BEGIN
    -- Calculate recency score (weighted by year)
    FOR v_record IN
        SELECT year, appeared,
            CASE year
                WHEN 2024 THEN 1.0
                WHEN 2023 THEN 0.8
                WHEN 2022 THEN 0.6
                WHEN 2021 THEN 0.4
                WHEN 2020 THEN 0.2
                ELSE 0.0
            END AS weight
        FROM exam_question_data
        WHERE subject = p_subject AND topic = p_topic
        ORDER BY year DESC
    LOOP
        IF v_record.appeared THEN
            v_recency_score := v_recency_score + v_record.weight;
            v_years_since_last := 0;
        ELSE
            v_years_since_last := v_years_since_last + 1;
        END IF;
    END LOOP;
    
    -- Calculate 3-year frequency
    SELECT COUNT(*) INTO v_frequency_3yr
    FROM exam_question_data
    WHERE subject = p_subject 
        AND topic = p_topic
        AND year >= p_current_year - 3
        AND appeared = TRUE;
    
    -- Get chapter weight
    SELECT COALESCE(chapter_weight, 3) INTO v_chapter_weight
    FROM exam_question_data
    WHERE subject = p_subject AND topic = p_topic
    LIMIT 1;
    
    -- Calculate priority
    v_priority := (
        (v_recency_score * 0.4) +
        (v_frequency_3yr::NUMERIC * 0.3 / 3.0) +
        ((5 - LEAST(v_years_since_last, 5))::NUMERIC * 0.1 / 5.0) +
        (v_chapter_weight::NUMERIC * 0.2 / 5.0)
    );
    
    -- Normalize to 0-1 range
    v_priority := LEAST(1.0, GREATEST(0.1, v_priority));
    
    RETURN v_priority;
END;

DECLARE
    v_latest_year INTEGER;
BEGIN
    -- Get the latest year with predictions
    SELECT MAX(year) INTO v_latest_year
    FROM exam_predictions
    WHERE subject = p_subject;
    
    IF v_latest_year IS NULL THEN
        RETURN QUERY SELECT 0.0::NUMERIC, 0, 0, '{}'::TEXT[], 0;
        RETURN;
    END IF;
    
    RETURN QUERY
    SELECT 
        er.readiness_percent,
        er.topics_mastered,
        er.total_predicted_topics,
        er.weak_topics,
        v_latest_year
    FROM get_exam_readiness_score(p_user_id, p_subject, v_latest_year) er;
END;

DECLARE
    v_total_topics INTEGER;
    v_mastered_count INTEGER := 0;
    v_weak_topics TEXT[] := '{}';
    v_predicted_topic TEXT;
    v_quiz_topic TEXT;
    v_quiz_score INTEGER;
BEGIN
    -- Get total predicted topics for this subject and year
    SELECT COUNT(*) INTO v_total_topics
    FROM exam_predictions
    WHERE subject = p_subject AND year = p_year;
    
    -- If no predictions exist, return default values
    IF v_total_topics = 0 THEN
        RETURN QUERY SELECT 0.0::NUMERIC, 0, 0, '{}'::TEXT[];
        RETURN;
    END IF;
    
    -- Check each predicted topic
    FOR v_predicted_topic IN
        SELECT ep.topic
        FROM exam_predictions ep
        WHERE ep.subject = p_subject AND ep.year = p_year
    LOOP
        -- Check if student has a mastered attempt for this topic (score >= 70)
        -- Using direct topic matching
        SELECT qa.topic, qa.score INTO v_quiz_topic, v_quiz_score
        FROM quiz_attempts qa
        WHERE qa.user_id = p_user_id 
            AND qa.subject = p_subject
            AND (qa.topic = v_predicted_topic
                 OR qa.topic ILIKE '%' || SPLIT_PART(v_predicted_topic, ' ', 1) || '%'
                 OR v_predicted_topic ILIKE '%' || qa.topic || '%')
            AND qa.score >= 70
        LIMIT 1;
        
        IF FOUND THEN
            v_mastered_count := v_mastered_count + 1;
        ELSE
            v_weak_topics := v_weak_topics || v_predicted_topic;
        END IF;
    END LOOP;
    
    RETURN QUERY
    SELECT 
        ROUND((v_mastered_count * 100.0) / v_total_topics, 2),
        v_mastered_count,
        v_total_topics,
        v_weak_topics;
END;

DECLARE
    v_total_prerequisites INTEGER;
    v_mastered_prerequisites INTEGER := 0;
    v_prereq_record RECORD;
BEGIN
    -- Get all prerequisites for this topic
    SELECT COUNT(*) INTO v_total_prerequisites
    FROM topic_prerequisites
    WHERE subject = p_subject AND topic = p_topic;
    
    -- If no prerequisites, return 1.0 (fully ready)
    IF v_total_prerequisites = 0 THEN
        RETURN 1.0;
    END IF;
    
    -- Check each prerequisite
    FOR v_prereq_record IN
        SELECT prerequisite_topic
        FROM topic_prerequisites
        WHERE subject = p_subject AND topic = p_topic
    LOOP
        -- Check if student has mastered this prerequisite (score >= 70)
        IF EXISTS (
            SELECT 1 FROM quiz_attempts qa
            WHERE qa.user_id = p_user_id
                AND qa.subject = p_subject
                AND qa.topic ILIKE '%' || v_prereq_record.prerequisite_topic || '%'
                AND qa.score >= 70
        ) THEN
            v_mastered_prerequisites := v_mastered_prerequisites + 1;
        END IF;
    END LOOP;
    
    -- Return ratio of mastered prerequisites
    RETURN v_mastered_prerequisites::NUMERIC / v_total_prerequisites;
END;
